std::size_t i, j, k, neighborIdx;
float dx, dy, dz, r2, r, inv_r, q, q2, q3;
float gradW, lapW;
float pressureI, pressureJ;
float densityI, densityJ;
float forceX, forceY, forceZ;
float velDiffX, velDiffY, velDiffZ;
float viscosityForceX, viscosityForceY, viscosityForceZ;
float totalForceX, totalForceY, totalForceZ;

for (i = start; i < end; ++i) {
    totalForceX = 0.0f;
    totalForceY = 0.0f;
    totalForceZ = 0.0f;
    viscosityForceX = 0.0f;
    viscosityForceY = 0.0f;
    viscosityForceZ = 0.0f;

    const Particle& pi = particles[i];
    pressureI = pi.pressure;
    densityI = pi.density;

    // Iterate over neighboring cells
    for (k = 0; k < 27; ++k) {
        std::size_t cellIdx = particleTable[27 * i + k];
        if (cellIdx == std::numeric_limits<std::uint32_t>::max()) continue;

        // Iterate over particles in neighboring cell
        for (j = 0; j < particleTable[cellIdx]; ++j) {
            neighborIdx = particleTable[cellIdx + 1 + j];
            if (neighborIdx == i) continue;  // Skip self

            const Particle& pj = particles[neighborIdx];
            pressureJ = pj.pressure;
            densityJ = pj.density;

            // Calculate distance between particles
            dx = pi.position.x - pj.position.x;
            dy = pi.position.y - pj.position.y;
            dz = pi.position.z - pj.position.z;
            r2 = dx*dx + dy*dy + dz*dz;

            if (r2 < h2 && r2 > 0.0f) {
                r = std::sqrt(r2);
                inv_r = 1.0f / r;
                q = r / h;
                q2 = q * q;
                q3 = q2 * q;

                // Spiky gradient kernel
                gradW = spikyGrad * (q3 - q) * inv_r;
                // Viscosity Laplacian kernel
                lapW = spikyLap * (1.0f - q);

                // Pressure force
                forceX = -mass * (pressureI + pressureJ) / (2.0f * densityJ) * gradW * dx * inv_r;
                forceY = -mass * (pressureI + pressureJ) / (2.0f * densityJ) * gradW * dy * inv_r;
                forceZ = -mass * (pressureI + pressureJ) / (2.0f * densityJ) * gradW * dz * inv_r;

                totalForceX += forceX;
                totalForceY += forceY;
                totalForceZ += forceZ;

                // Viscosity force
                velDiffX = pj.velocity.x - pi.velocity.x;
                velDiffY = pj.velocity.y - pi.velocity.y;
                velDiffZ = pj.velocity.z - pi.velocity.z;

                viscosityForceX += viscosity * mass * velDiffX / densityJ * lapW;
                viscosityForceY += viscosity * mass * velDiffY / densityJ * lapW;
                viscosityForceZ += viscosity * mass * velDiffZ / densityJ * lapW;
            }
        }
    }

    // Update particle forces
    pi.force.x += totalForceX + viscosityForceX;
    pi.force.y += totalForceY + viscosityForceY;
    pi.force.z += totalForceZ + viscosityForceZ;
}
// END_CODE

